DROP TABLE IF EXISTS lookups
CREATE TABLE lookups (name TEXT PRIMARY KEY NOT NULL, enabled NUMERIC NOT NULL, position NUMERIC NOT NULL, URL TEXT NOT NULL)
insert into lookups(name,enabled,position,URL) values('Logeion iOS App',1,0,'LogeionLookUp://<word>')
insert into lookups(name,enabled,position,URL) values('Logeion Web',1,1,'https://logeion.uchicago.edu/<word>')
insert into lookups(name,enabled,position,URL) values('Blue Letter Bible',1,2,'https://www.blueletterbible.org/lexicon/G<id>/<bible>')
insert into lookups(name,enabled,position,URL) values('BibleHub',1,3,'https://biblehub.com/greek/<id>.htm')
insert into lookups(name,enabled,position,URL) values('NetBible',1,4,'https://classic.net.bible.org/strong.php?id=<id>')
insert into lookups(name,enabled,position,URL) values('Wiktionary',1,5,'https://en.wiktionary.org/wiki/<word>')

DROP TABLE IF EXISTS gntsp_temp_table
CREATE TABLE gntsp_temp_table AS SELECT * FROM dictionary
DROP TABLE dictionary
CREATE TABLE dictionary (lemma TEXT PRIMARY KEY ON CONFLICT IGNORE NOT NULL COLLATE NOCASE, pos TEXT NOT NULL, lookup TEXT NOT NULL COLLATE NOCASE, display TEXT NOT NULL, gloss TEXT NOT NULL, count INTEGER NOT NULL, strongs TEXT NOT NULL DEFAULT 0)
INSERT INTO dictionary (lemma,pos,lookup,display,gloss,count) SELECT lemma,pos,lookup,display,gloss,count FROM gntsp_temp_table
DROP TABLE gntsp_temp_table
CREATE INDEX dictionary_gloss_index ON dictionary (gloss)
CREATE INDEX dictionary_lookup_index ON dictionary (lookup)
CREATE INDEX dictionary_strongs_index ON dictionary (strongs)

